const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const a = [];
let zeroRow = 0;
let zeroCol = 0;
let idx = 1;

for (let i = 0; i < n; i++) {
  a[i] = [];
  for (let j = 0; j < n; j++) {
    const v = data[idx++];
    a[i][j] = v;
    if (v === 0) {
      zeroRow = i;
      zeroCol = j;
    }
  }
}

let magicSum = 0;
for (let i = 0; i < n; i++) {
  if (i !== zeroRow) {
    let sum = 0;
    for (let j = 0; j < n; j++) {
      sum += a[i][j];
    }
    magicSum = sum;
    break;
  }
}

let zeroRowSum = 0;
for (let j = 0; j < n; j++) {
  zeroRowSum += a[zeroRow][j];
}

const missing = magicSum - zeroRowSum;

console.log(missing);
console.log(zeroRow + 1);
console.log(zeroCol + 1);
